<template><MainLayout><div class="page-card"><div class="toolbar"><a-button type="primary" @click="newYear">创建下一年度账套</a-button></div><a-table :data="items"><template #columns><a-table-column title="年度" data-index="year_no"/><a-table-column title="额度" data-index="annual_limit"/><a-table-column title="允许补登"><template #cell="{record}">{{record.allow_backfill?'是':'否'}}</template></a-table-column><a-table-column title="状态" data-index="status"/><a-table-column title="操作"><template #cell="{record}"><a-button size="small" @click="edit(record)">编辑</a-button><a-popconfirm v-if="!record.is_default" content="确认删除该年度账套？仅无业务数据账套允许删除。" @ok="remove(record)"><a-button size="small" status="danger">删除</a-button></a-popconfirm></template></a-table-column></template></a-table><a-modal v-model:visible="visible" title="年度账套"><a-form :model="form"><a-form-item field="annualLimit" label="年度额度"><a-input-number v-model="form.annualLimit" :min="0"/></a-form-item><a-form-item field="invoiceStartDate" label="发票起始"><a-input v-model="form.invoiceStartDate"/></a-form-item><a-form-item field="invoiceEndDate" label="发票结束"><a-input v-model="form.invoiceEndDate"/></a-form-item><a-form-item field="allowBackfill" label="允许补登"><a-switch v-model="form.allowBackfill"/></a-form-item><a-form-item field="remark" label="备注"><a-textarea v-model="form.remark"/></a-form-item></a-form><template #footer><a-button @click="visible=false">取消</a-button><a-button type="primary" @click="save">保存</a-button></template></a-modal></div></MainLayout></template>
<script setup>
import {ref,onMounted,reactive} from 'vue';import MainLayout from '../layouts/MainLayout.vue';import {adminYears,initYear,updateYear,deleteYear} from '../api/admin';import {Message} from '@arco-design/web-vue';const items=ref([]),visible=ref(false),editing=ref(null),form=reactive({annualLimit:0,invoiceStartDate:'',invoiceEndDate:'',allowBackfill:false,remark:''});const error=e=>Message.error(e.message||'操作失败',5000);const load=async()=>{try{const r=await adminYears();items.value=r.data}catch(e){error(e)}};const edit=r=>{editing.value=r;Object.assign(form,{annualLimit:Number(r.annual_limit),invoiceStartDate:r.invoice_start_date,invoiceEndDate:r.invoice_end_date,allowBackfill:r.allow_backfill,remark:r.remark||''});visible.value=true};const newYear=async()=>{try{const src=items.value.find(x=>x.is_default)||items.value[0];if(!src)throw new Error('没有可用于初始化的来源账套');await initYear({sourceYearId:src.id,targetYear:Number(src.year_no)+1});Message.success('已创建草稿账套');load()}catch(e){error(e)}};const save=async()=>{try{await updateYear(editing.value.id,form);visible.value=false;Message.success('账套已保存');load()}catch(e){error(e)}};const remove=async r=>{try{await deleteYear(r.id);Message.success('账套已删除');load()}catch(e){error(e)}};onMounted(load);
</script>
